package httpserver

import (
	"io"
	"net/http"
)

func renderResultsWorkspace(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = io.WriteString(w, resultsWorkspacePage)
}

func resultsWorkspaceScript(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	_, _ = io.WriteString(w, resultsWorkspaceJavaScript)
}

const resultsWorkspacePage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>批复与审计结果</title><style>` + resultsWorkspaceCSS + `[hidden]{display:none!important}</style></head><body>
<header class="top"><a class="brand" href="./"><span>AR</span><strong>批复与审计结果</strong></a><div class="credential"><span id="credentialState">尚未连接</span><button id="openCredential" class="quiet">设置访问凭证</button></div></header>
<div class="layout"><aside class="rail"><p class="eyebrow">结果工作区</p><button class="nav active" data-view="overview">使用说明</button><button class="nav" data-view="workspace">结果登记</button><div class="rail-note"><strong>边界</strong><span>本应用登记外部结果及精确来源，不拥有 Project、合同或文件字节。</span></div></aside><main>
<section id="overview" class="view active"><div class="hero"><p class="eyebrow">Approval &amp; Audit Results</p><h1>把外部批复和审计结论，变成可纠正、可撤回、可追溯的事实。</h1><p>先输入 Project ID 读取当前批复／审计，再按顺序登记。审计引用已经登记的批复 revision；任何更正都会形成新 revision，而不是覆盖历史。</p><button class="primary" data-go="workspace">开始登记</button></div><div class="flow"><article><b>01</b><h2>选定 Project</h2><p>读取当前结果和你的允许动作。</p></article><article><b>02</b><h2>登记批复</h2><p>冻结合同／结算的精确 revision 与金额。</p></article><article><b>03</b><h2>登记审计</h2><p>引用批复的精确 revision，形成独立结果。</p></article></div></section>
<section id="workspace" class="view"><div class="section-head"><div><p class="eyebrow">Project 范围</p><h1>批复与审计结果登记</h1></div><button id="newResult" class="primary" disabled>登记结果</button></div>
<form id="projectForm" class="project-bar"><label>Project ID<input id="projectID" required placeholder="稳定 UUID"></label><button class="quiet" type="submit">读取当前结果</button></form>
<div id="notice" class="notice">设置访问凭证并输入 Project ID。页面不会把“无权查看”伪装成“没有结果”。</div>
<div class="workspace-grid"><section class="panel"><div class="panel-head"><div><h2>当前结果</h2><span id="projectContext">尚未选择 Project</span></div><button id="reload" class="quiet" disabled>重新读取</button></div><div id="resultList" class="result-list"><div class="empty"><strong>还没有读取业务事实</strong><span>从上方输入 Project ID 开始。</span></div></div></section>
<aside class="panel detail"><div class="panel-head"><div><h2>历史与恢复</h2><span>选择结果后读取不可变 revision。</span></div></div><div id="historyList" class="timeline"><div class="empty">历史按需读取。</div></div></aside></div>
</section></main></div>
<dialog id="credentialDialog"><form method="dialog" id="credentialForm"><p class="eyebrow">访问控制</p><h2>连接受保护 API</h2><p>本地开发粘贴模板 Token；正式组合由 Gateway 从 IAM 会话换取短期凭证。Token 只保存在当前标签页。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">保存并连接</button></div></form></dialog>
<dialog id="resultDialog"><form method="dialog" id="resultForm"><p class="eyebrow" id="formEyebrow">登记结果</p><h2 id="formTitle">登记批复或审计</h2><input name="result_id" type="hidden"><input name="mode" type="hidden" value="create"><div class="form-grid"><label>结果类型<select name="kind"><option value="approval">批复 approval</option><option value="audit">审计 audit</option></select></label><label>Project revision<input name="project_revision" type="number" min="1" required></label><label>来源应用<input name="source_application" value="contract-ledger" required></label><label>来源类型<input name="source_type" value="contract" required></label><label class="wide">来源资源 ID<input name="source_id" required placeholder="合同／结算或批复结果 UUID"></label><label>来源 revision<input name="source_revision" type="number" min="1" required></label><label>外部确认人／文书<input name="confirmed_by" required></label><label>外部确认时间<input name="confirmed_at" type="datetime-local" required></label><label class="wide">人工覆盖原因<textarea name="override_reason" rows="2" placeholder="仅当金额与来源不同才填写"></textarea></label></div>
<details><summary>可选：人工金额与 Evidence</summary><div class="form-grid advanced"><label>设计费（分）<input name="design_fee" type="number" min="0"></label><label>勘察费（分）<input name="survey_fee" type="number" min="0"></label><label>咨询费（分）<input name="consultation_fee" type="number" min="0"></label><label>Evidence File ID<input name="evidence_id"></label><label>Evidence version<input name="evidence_version" type="number" min="1"></label><label>Evidence 槽位<input name="evidence_slot" placeholder="approval_document"></label></div></details>
<label id="reasonField" hidden>更正原因<textarea name="reason" rows="2"></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">提交并读取结果</button></div></form></dialog>
<script src="assets/results.js"></script></body></html>`

const resultsWorkspaceCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,sans-serif;color:#18212f;background:#f4f6f8;line-height:1.55;--ink:#18212f;--muted:#667085;--line:#dce1e8;--soft:#f7f8fa;--accent:#3157a4;--danger:#a93a33}*{box-sizing:border-box}body{margin:0}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fff;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);text-decoration:none}.brand span{display:grid;place-items:center;width:34px;height:34px;border-radius:7px;background:#243b66;color:#fff;font-size:12px;font-weight:800}.credential{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:13px}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:calc(100vh - 64px)}.rail{padding:26px 18px;background:#fff;border-right:1px solid var(--line)}.eyebrow{margin:0 0 9px;color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.nav{width:100%;padding:11px 13px;border:0;border-left:3px solid transparent;background:transparent;color:#4d596b;text-align:left;font:inherit;cursor:pointer}.nav.active{border-color:var(--accent);background:#edf3fb;color:var(--accent);font-weight:750}.rail-note{display:grid;gap:5px;margin-top:32px;padding:14px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}main{min-width:0;padding:30px}.view{display:none}.view.active{display:block}.hero{min-height:340px;padding:54px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(120deg,#fff 65%,#eaf0f8)}h1,h2,p{margin-top:0}.hero h1{max-width:790px;margin-bottom:18px;font-size:clamp(34px,5vw,56px);line-height:1.08;letter-spacing:-.04em}.hero>p:not(.eyebrow){max-width:730px;color:var(--muted);font-size:17px}.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}.flow article,.panel{border:1px solid var(--line);border-radius:10px;background:#fff}.flow article{padding:22px}.flow b{color:var(--accent)}.flow h2{margin:12px 0 6px;font-size:17px}.flow p{margin:0;color:var(--muted);font-size:13px}.primary,.quiet,.danger{padding:9px 13px;border:1px solid transparent;border-radius:6px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.quiet{border-color:var(--line);background:#fff;color:#3f4a5a}.danger{background:var(--danger);color:#fff}.primary:disabled,.quiet:disabled{opacity:.45;cursor:not-allowed}.section-head,.panel-head,.card-head,.dialog-actions{display:flex;align-items:center;justify-content:space-between;gap:16px}.section-head{margin-bottom:16px}.section-head h1{margin:0;font-size:28px}.project-bar{display:grid;grid-template-columns:minmax(280px,620px) auto;gap:10px;align-items:end;padding:14px;border:1px solid var(--line);border-radius:9px;background:#fff}.notice{margin:12px 0;padding:11px 14px;border:1px solid #cad8ea;border-radius:7px;background:#eef4fb;color:#315477;font-size:13px}.notice.ok{border-color:#bce0cb;background:#eefaf3;color:#15623d}.notice.error{border-color:#efc6c6;background:#fff2f2;color:#922}.workspace-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(320px,.8fr);gap:16px}.panel{min-height:520px;padding:18px}.panel-head{padding-bottom:14px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:18px}.panel-head span{color:var(--muted);font-size:12px}.result-list{display:grid;gap:12px;margin-top:14px}.result-card{padding:16px;border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:8px}.result-card.withdrawn{border-left-color:var(--danger);background:#fff9f9}.card-head h3{margin:0;font-size:17px}.badges,.actions{display:flex;flex-wrap:wrap;gap:6px}.badge{padding:3px 8px;border-radius:999px;background:#eef1f4;color:#566273;font-size:11px;font-weight:750}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:14px 0}.fact{padding:10px;background:var(--soft);border-radius:6px}.fact small{display:block;color:var(--muted)}.fact strong{font-size:13px}.source{margin:0 0 13px;color:var(--muted);font-size:12px}.empty{display:grid;gap:5px;place-content:center;min-height:180px;color:var(--muted);text-align:center}.timeline{display:grid;gap:9px;margin-top:14px}.event{padding:12px;border-left:3px solid #bdc6d2;background:var(--soft);font-size:12px}.event strong{display:block;color:var(--ink)}label{display:grid;gap:5px;color:#4c5667;font-size:12px;font-weight:700}input,textarea,select{width:100%;padding:9px 10px;border:1px solid #cbd2dc;border-radius:5px;background:#fff;color:var(--ink);font:inherit;font-size:13px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.wide{grid-column:1/-1}details{margin-top:14px;padding:10px;border:1px solid var(--line);border-radius:7px}summary{cursor:pointer;color:var(--accent);font-size:13px;font-weight:700}.advanced{margin-top:10px}dialog{width:min(760px,calc(100vw - 32px));padding:24px;border:1px solid var(--line);border-radius:11px;box-shadow:0 18px 50px #18212f2a}dialog::backdrop{background:#18212f66}.dialog-actions{margin-top:18px;justify-content:flex-end}@media(max-width:900px){.layout{grid-template-columns:1fr}.rail{display:none}main{padding:18px}.flow,.workspace-grid{grid-template-columns:1fr}.project-bar{grid-template-columns:1fr}.facts{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}`

const resultsWorkspaceJavaScript = `const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],state={token:sessionStorage.getItem('results-demo-token')||'',projectID:'',items:[]};
const A={correct:'approval-audit-result.correct',withdraw:'approval-audit-result.withdraw',history:'approval-audit-result.history.read'};
function notice(message,kind=''){const n=$('#notice');n.textContent=message;n.className='notice '+kind}
function setCredential(){state.token=$('#token').value.trim();sessionStorage.setItem('results-demo-token',state.token);$('#credentialState').textContent=state.token?'凭证已保存在当前标签页':'尚未连接'}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{Accept:'application/json',Authorization:'Bearer '+state.token,...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(body.error?.code||'HTTP_'+response.status);error.status=response.status;error.retryable=body.error?.retryable;throw error}return body}
function money(v){return v==null?'金额未授权':new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format(v/100)}
function can(item,action){return (item.allowed_actions||[]).includes(action)}
function escapeText(value){const span=document.createElement('span');span.textContent=value??'';return span.innerHTML}
function render(){const root=$('#resultList');root.replaceChildren();$('#newResult').disabled=!state.projectID;if(!state.items.length){root.innerHTML='<div class="empty"><strong>这个 Project 还没有批复或审计结果</strong><span>先登记批复，再以批复的精确 revision 登记审计。</span></div>';return}for(const item of state.items){const card=document.createElement('article');card.className='result-card '+item.state;const actions=[];if(can(item,A.history))actions.push('<button class="quiet" data-history="'+item.id+'">读取历史</button>');if(can(item,A.correct)&&item.state==='recorded')actions.push('<button class="quiet" data-correct="'+item.id+'">追加更正</button>');if(can(item,A.withdraw)&&item.state==='recorded')actions.push('<button class="danger" data-withdraw="'+item.id+'">撤回</button>');card.innerHTML='<div class="card-head"><div><h3>'+(item.kind==='approval'?'批复结果':'审计结果')+'</h3><div class="badges"><span class="badge">'+escapeText(item.state)+'</span><span class="badge">revision '+item.revision+'</span></div></div><div class="actions">'+actions.join('')+'</div></div><div class="facts"><div class="fact"><small>合计</small><strong>'+money(item.total_amount_minor)+'</strong></div><div class="fact"><small>外部确认</small><strong>'+escapeText(item.external_confirmed_by)+'</strong></div><div class="fact"><small>Evidence</small><strong>'+item.evidence.length+' 个精确版本</strong></div></div><p class="source">来源：'+escapeText(item.source.application)+' / '+escapeText(item.source.resource_type)+' / '+escapeText(item.source.resource_id)+' · r'+item.source.revision+'<br>结果 ID：'+item.id+'</p>';root.append(card)}}
async function load(){if(!state.token){$('#credentialDialog').showModal();return}state.projectID=$('#projectID').value.trim().toLowerCase();if(!state.projectID)return;try{notice('正在读取当前结果与权限…');const data=await api('/api/v1/approval-audit-results?project_id='+encodeURIComponent(state.projectID));state.items=data.items||[];$('#projectContext').textContent=state.projectID;$('#reload').disabled=false;render();notice('已读取 '+state.items.length+' 条当前结果；动作已按服务端权限收敛。','ok')}catch(error){state.items=[];render();notice(error.status===403?'当前凭证无权读取该 Project。':'读取失败：'+error.message+(error.retryable?'，依赖恢复后可重试。':''),'error')}}
function openCreate(current){const f=$('#resultForm');f.reset();f.elements.mode.value=current?'correct':'create';f.elements.result_id.value=current?.id||'';f.elements.project_revision.value=current?.project.revision||'';f.elements.confirmed_at.value=(current?new Date(current.external_confirmed_at):new Date()).toISOString().slice(0,16);$('#reasonField').hidden=!current;f.elements.reason.required=!!current;if(current){$('#formEyebrow').textContent='追加更正';$('#formTitle').textContent=current.kind==='approval'?'更正批复结果':'更正审计结果';f.elements.kind.value=current.kind;f.elements.kind.disabled=true;f.elements.source_application.value=current.source.application;f.elements.source_type.value=current.source.resource_type;f.elements.source_id.value=current.source.resource_id;f.elements.source_revision.value=current.source.revision;f.elements.confirmed_by.value=current.external_confirmed_by;f.elements.override_reason.value=current.override_reason||'';for(const c of current.amount_components||[])if(f.elements[c.kind])f.elements[c.kind].value=c.amount_minor;const e=current.evidence?.[0];if(e){f.elements.evidence_id.value=e.file_id;f.elements.evidence_version.value=e.version;f.elements.evidence_slot.value=e.slot}}else{$('#formEyebrow').textContent='登记结果';$('#formTitle').textContent='登记批复或审计';f.elements.kind.disabled=false;f.elements.kind.value=state.items.some(x=>x.kind==='approval'&&x.state==='recorded')?'audit':'approval';syncKind()}$('#resultDialog').showModal()}
function syncKind(){const f=$('#resultForm'),audit=f.elements.kind.value==='audit';f.elements.source_application.value=audit?'approval-audit-results':'contract-ledger';f.elements.source_type.value=audit?'approval-result':'contract';if(audit){const approval=state.items.find(x=>x.kind==='approval'&&x.state==='recorded');if(approval){f.elements.source_id.value=approval.id;f.elements.source_revision.value=approval.revision}}}
function payload(form){const components=['design_fee','survey_fee','consultation_fee'].map(kind=>({kind,amount_minor:Number(form.elements[kind].value)}));const hasAmounts=['design_fee','survey_fee','consultation_fee'].some(kind=>form.elements[kind].value!=='');const evidence=form.elements.evidence_id.value.trim()?[{file_id:form.elements.evidence_id.value.trim(),version:Number(form.elements.evidence_version.value),slot:form.elements.evidence_slot.value.trim()}]:[];return {command_id:crypto.randomUUID(),expected_revision:form.elements.mode.value==='create'?0:state.items.find(x=>x.id===form.elements.result_id.value).revision,project_ref:{id:state.projectID,revision:Number(form.elements.project_revision.value)},kind:form.elements.kind.value,currency:'CNY',...(hasAmounts?{amount_components:components}:{}),source_ref:{application:form.elements.source_application.value.trim(),resource_type:form.elements.source_type.value.trim(),resource_id:form.elements.source_id.value.trim(),revision:Number(form.elements.source_revision.value)},evidence_refs:evidence,override_reason:form.elements.override_reason.value.trim(),external_confirmed_by:form.elements.confirmed_by.value.trim(),external_confirmed_at:new Date(form.elements.confirmed_at.value).toISOString(),...(form.elements.mode.value==='correct'?{reason:form.elements.reason.value.trim()}: {})}}
$$('.nav').forEach(b=>b.onclick=()=>{$$('.nav').forEach(x=>x.classList.toggle('active',x===b));$$('.view').forEach(v=>v.classList.toggle('active',v.id===b.dataset.view))});$$('[data-go]').forEach(b=>b.onclick=()=>$('.nav[data-view="'+b.dataset.go+'"]').click());
$('#openCredential').onclick=()=>{$('#token').value=state.token;$('#credentialDialog').showModal()};$('#credentialForm').onsubmit=e=>{if(e.submitter?.value==='cancel')return;setCredential();setTimeout(load)};$('#projectForm').onsubmit=e=>{e.preventDefault();load()};$('#reload').onclick=load;$('#newResult').onclick=()=>openCreate();$('#resultForm').elements.kind.onchange=syncKind;
$('#resultForm').onsubmit=async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const f=e.currentTarget,data=payload(f),correct=f.elements.mode.value==='correct';if(correct){delete data.project_ref;delete data.kind}try{notice(correct?'正在追加更正…':'正在登记结果…');await api(correct?'/api/v1/approval-audit-results/'+f.elements.result_id.value+'/corrections':'/api/v1/approval-audit-results',{method:'POST',body:JSON.stringify(data)});$('#resultDialog').close();await load();notice(correct?'更正已追加，旧 revision 仍可在历史中读取。':'结果已登记。','ok')}catch(error){notice('提交失败：'+error.message+(error.status===409?'。请重新读取最新 revision。':''),'error')}};
$('#resultList').onclick=async e=>{const history=e.target.closest('[data-history]'),correct=e.target.closest('[data-correct]'),withdraw=e.target.closest('[data-withdraw]');if(history){try{const data=await api('/api/v1/approval-audit-results/'+history.dataset.history+'/history');$('#historyList').innerHTML=(data.items||[]).map(x=>'<div class="event"><strong>'+escapeText(x.event_kind)+' · revision '+x.revision+'</strong>'+escapeText(x.reason)+'<br>'+new Date(x.occurred_at).toLocaleString('zh-CN')+'</div>').join('')||'<div class="empty">没有历史。</div>'}catch(error){notice('历史读取失败：'+error.message,'error')}}if(correct)openCreate(state.items.find(x=>x.id===correct.dataset.correct));if(withdraw){const item=state.items.find(x=>x.id===withdraw.dataset.withdraw),reason=prompt('请输入撤回原因');if(!reason)return;try{await api('/api/v1/approval-audit-results/'+item.id+'/withdrawal',{method:'POST',body:JSON.stringify({command_id:crypto.randomUUID(),expected_revision:item.revision,reason})});await load();notice('结果已显式撤回，历史仍保留。','ok')}catch(error){notice('撤回失败：'+error.message,'error')}}};
$('#credentialState').textContent=state.token?'凭证已保存在当前标签页':'尚未连接';const requested=new URLSearchParams(location.search).get('project_id');if(requested){$('#projectID').value=requested;$('.nav[data-view="workspace"]').click();if(state.token)load()}`
